package com.rj1399.customersupport.agent;
import org.springframework.stereotype.Component; import java.time.Instant; import java.util.*; import java.util.concurrent.*;
@Component public class AgentTraceStore { private final Map<String,List<AgentTrace>> traces=new ConcurrentHashMap<>(); public String start(){String id=UUID.randomUUID().toString(); traces.put(id,new CopyOnWriteArrayList<>()); event(id,AgentTrace.TraceEventType.AGENT_STARTED,"orchestrator","resolve",0,Map.of()); return id;} public void add(AgentTrace trace){traces.computeIfAbsent(trace.executionId(),k->new CopyOnWriteArrayList<>()).add(trace);} public void event(String id,String type,String component,String operation){event(id,AgentTrace.TraceEventType.valueOf(type),component,operation,0,Map.of());} public void event(String id,AgentTrace.TraceEventType type,String component,String operation,long duration,Map<String,Object> metadata){add(new AgentTrace(id,Instant.now(),type,component,operation,duration,metadata));} public List<AgentTrace> get(String id){return List.copyOf(traces.getOrDefault(id,List.of()));} public void complete(String id){event(id,AgentTrace.TraceEventType.AGENT_COMPLETED,"orchestrator","resolve",0,Map.of());} }
